 function legend(){const l=E('div',undefined,'lx-legend');for(const [cls,text]of [['today','Today'],['events','Report / appointment'],['verified','Verified lead · +commission'],['weekend','Weekend']]){const i=E('span',undefined,'lx-legend-item');i.append(E('i',undefined,'lx-legend-'+cls),E('span',text));l.append(i);}return l;}
