  const links=E('div',undefined,'lx-hero-links'),cardBtn=button('',()=>navigate('card')),rep=button('',()=>{selectedDay=dateKey();month=new Date(Number(selectedDay.slice(0,4)),Number(selectedDay.slice(5,7))-1,1);navigate('calendar');});cardBtn.append(icon('card','lx-btn-icon'),E('span','My card'));rep.append(icon('planner','lx-btn-icon'),E('span','Daily report'));cardBtn.classList.add('lx-chip-btn');rep.classList.add('lx-chip-btn');links.append(cardBtn,rep);
